challenge_result.network_analysis:
{
  "summary": "The network is experiencing a catastrophic data plane failure originating from the RAN, which has overwhelmed the UPF and caused a complete outage of both user data and IMS control plane services.",
  "layer_status": {
    "ran": {
      "rating": "red",
      "evidence": [
        "normalized.upf.gtp_indatapktn3upf_per_ue"
      ],
      "note": "The RAN is the suspected source of a massive packet storm on the N3 interface, indicated by an extreme spike in the UPF's ingress traffic rate."
    },
    "core": {
      "rating": "red",
      "evidence": [
        "normalized.upf.gtp_indatapktn3upf_per_ue",
        "normalized.upf.gtp_outdatapktn3upf_per_ue"
      ],
      "note": "The UPF is non-functional. It is receiving an anomalous flood of uplink packets but is transmitting zero packets, indicating it is either overwhelmed or has an internal fault."
    },
    "ims": {
      "rating": "yellow",
      "evidence": [
        "normalized.pcscf.core:rcv_requests_register_per_ue",
        "normalized.icscf.core:rcv_requests_register_per_ue",
        "normalized.scscf.core:rcv_requests_register_per_ue"
      ],
      "note": "The entire IMS registration chain is silent. This is a downstream consequence of the data plane failure, as SIP signaling from the UE cannot reach the P-CSCF."
    },
    "infrastructure": {
      "rating": "green",
      "evidence": [
        "get_network_status"
      ],
      "note": "All network function containers are running."
    }
  },
  "hypotheses": [
    {
      "id": "h1",
      "statement": "The nr_gnb is the source of the anomalous behavior, generating a massive volume of uplink GTP-U packets that is overwhelming the UPF. This data plane flood has caused the UPF to stop forwarding any traffic, leading to the observed outage in both user data and IMS signaling.",
      "primary_suspect_nf": "nr_gnb",
      "supporting_events": [],
      "explanatory_fit": 0.8,
      "falsification_probes": [
        "Check the gNB's own transmit counters for the N3 interface. If they do not show a corresponding spike in transmitted packets, the gNB is not the source.",
        "Check the UPF container's CPU and memory utilization. If they are normal, the UPF is not overwhelmed by the traffic volume."
      ],
      "specificity": "specific"
    },
    {
      "id": "h2",
      "statement": "The UPF is the source of the anomaly. It has an internal fault causing it to drop all egress packets and incorrectly report a massive spike in ingress packets. This explains the zero downlink traffic and the collapse of all services that depend on the data plane.",
      "primary_suspect_nf": "upf",
      "supporting_events": [],
      "explanatory_fit": 0.6,
      "falsification_probes": [
        "Inspect kernel-level packet counters on the UPF's N3 interface (e.g., via `tc`). If the kernel's ingress packet count does not match the anomalous metric value, the metric reporting is faulty.",
        "Inspect the UPF's logs for error messages related to packet processing, forwarding loops, or metric reporting."
      ],
      "specificity": "moderate"
    }
  ]
}

challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "The nr_gnb is the source of the anomalous behavior, generating a massive volume of uplink GTP-U packets that is overwhelming the UPF. This data plane flood has caused the UPF to stop forwarding any traffic, leading to the observed outage in both user data and IMS signaling.",
      "primary_suspect_nf": "nr_gnb",
      "probes": [
        {
          "tool": "get_diagnostic_metrics",
          "args_hint": "Get metrics for 'nr_gnb', specifically the N3 interface transmit counters (e.g., 'gnb.gtp_outdatapktsn3').",
          "expected_if_hypothesis_holds": "The rate of the 'gnb.gtp_outdatapktsn3' metric is anomalously high, at a level consistent with the ingress traffic spike observed at the UPF.",
          "falsifying_observation": "The rate of the 'gnb.gtp_outdatapktsn3' metric is within its normal range or zero.",
          "conflates_with": []
        },
        {
          "tool": "get_diagnostic_metrics",
          "args_hint": "Get metrics for 'upf', specifically CPU and memory utilization.",
          "expected_if_hypothesis_holds": "The 'upf.cpu_utilization' and/or 'upf.memory_utilization' metrics are abnormally high (e.g., >90%).",
          "falsifying_observation": "The 'upf.cpu_utilization' and 'upf.memory_utilization' metrics are within normal operational ranges.",
          "conflates_with": []
        },
        {
          "tool": "get_network_status",
          "args_hint": "Check the running status of the 'nr_gnb' container.",
          "expected_if_hypothesis_holds": "The 'nr_gnb' container has a 'running' status.",
          "falsifying_observation": "The 'nr_gnb' container does not have a 'running' status.",
          "conflates_with": []
        }
      ],
      "notes": "The probes are designed to directly test the two main claims in the hypothesis: that the gNB is transmitting a packet flood, and that this flood is overwhelming the UPF. These are derived from the falsification probes suggested in the Network Analyst report."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "The UPF is the source of the anomaly. It has an internal fault causing it to drop all egress packets and incorrectly report a massive spike in ingress packets. This explains the zero downlink traffic and the collapse of all services that depend on the data plane.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "get_diagnostic_metrics",
          "args_hint": "Get metrics for 'nr_gnb', specifically to compare its N3 transmit counter ('gnb.gtp_outdatapktsn3') with the UPF's N3 ingress counter.",
          "expected_if_hypothesis_holds": "The rate of the 'gnb.gtp_outdatapktsn3' metric is normal or zero, showing a major discrepancy with the anomalous ingress rate reported by the UPF.",
          "falsifying_observation": "The rate of the 'gnb.gtp_outdatapktsn3' metric is anomalously high and corresponds to the ingress rate reported by the UPF.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check KB candidate #2 for h2. This returns the rate-windowed UPF egress packets per second toward the RAN.",
          "expected_if_hypothesis_holds": "The 'upf.gtp_outdatapktn3upf_per_ue' rate is zero, indicating no egress traffic.",
          "falsifying_observation": "The 'upf.gtp_outdatapktn3upf_per_ue' rate is greater than zero.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check KB candidate #3 for h2. This correlates active calls with data plane activity through the UPF.",
          "expected_if_hypothesis_holds": "The 'upf.activity_during_calls' metric is at or near 0.0, indicating no media flow despite active calls.",
          "falsifying_observation": "The 'upf.activity_during_calls' metric is at or near 1.0, indicating media is flowing consistently with active calls.",
          "conflates_with": []
        }
      ],
      "notes": "This plan tests the 'UPF internal fault' hypothesis by checking for the claimed effects: misreported ingress counters and a complete drop of egress packets. Probes are based on the Network Analyst report's suggestions and the KB-curated candidates for h2."
    }
  ]
}
